use vstd::prelude::*;

verus! {

fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> (index: Option<usize>)
    ensures
        // If we return Some(i), it is a valid index, arr[i] == target,
        // and i is the first occurrence (no earlier position equals target).
        match index {
            Some(i) => i < arr.len()
                && arr[i] == target
                && forall|j: int| 0 <= j < i as int ==> arr[j as usize] != target,
            // If we return None, then target does not occur in the array.
            None => forall|j: int| 0 <= j < arr.len() as int ==> arr[j as usize] != target,
        }
{
    let mut left: usize = 0;
    let mut right: usize = arr.len(); // exclusive

    // Find the first index where arr[i] >= target (lower_bound)
    while left < right
        invariant
            left <= right,
            right <= arr.len(),
            // All indices strictly before left are < target
            forall|j: int| 0 <= j < left as int ==> arr[j as usize] < target,
            // All indices at/after right are >= target
            forall|j: int| right as int <= j < arr.len() as int ==> arr[j as usize] >= target,
        decreases right - left
    {
        let mid = left + (right - left) / 2;

        assert(left <= mid);
        assert(mid < right);
        assert(mid < arr.len());

        if arr[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    // At loop exit: left == right, and it is the lower_bound.
    assert(left == right);
    assert(left <= arr.len());

    if left < arr.len() && arr[left] == target {
        // Show minimality: for any j < left, arr[j] < target, hence != target.
        assert(forall|j: int| 0 <= j < left as int ==> arr[j as usize] != target);
        Some(left)
    } else {
        // Need to show target is absent everywhere.
        // For j < left: arr[j] < target (hence != target).
        // For j >= left: since right == left and invariant gives arr[j] >= target,
        // and additionally arr[left] != target when left < len, we get arr[j] != target.
        //
        // NOTE: This relies on the usual lower_bound correctness property plus the check
        // arr[left] == target; if false, then no index has arr[i] == target.
        assert(forall|j: int| 0 <= j < arr.len() as int ==> arr[j as usize] != target);
        None
    }
}

} // verus!